     R,G,B=im[y,x]
     chrom=(B-max(R,G)) if kind=='b' else ((R+G)/2-B)
     if chrom>10: vals.append(im[y,x])
  if vals: print(rad,len(vals),np.mean(vals,axis=0).round(1))
